mapper.insert:
-- -- each format has a component table which they can extend -- CREATE TABLE IF NOT EXISTS ${format}_component ( component_id INT GENERATED BY DEFAULT AS IDENTITY, repository_id INT NOT NULL, namespace VARCHAR NOT NULL, name VARCHAR NOT NULL, kind VARCHAR NOT NULL, version VARCHAR NOT NULL, normalized_version VARCHAR, attributes ${JSON_TYPE} NOT NULL, created TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, last_updated TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, entity_version INT,
CONSTRAINT pk_${format}_component_id PRIMARY KEY (component_id), CONSTRAINT uk_${format}_component_coordinate UNIQUE (repository_id, namespace, name, version),
CONSTRAINT fk_${format}_component_repository FOREIGN KEY (repository_id) REFERENCES ${format}_content_repository (repository_id) );
-- This index was added via an uprade step task, see CoordinateMigrationStep_2_13, hence why this is commented out -- CREATE INDEX IF NOT EXISTS idx_${format}_component_coordinate ON ${format}_component (repository_id, namespace, name, version);

