SELECT * FROM ${format}_component
WHERE repository_id = #{repositoryId}
AND EXISTS (
  SELECT 1 FROM ${format}_asset a
  WHERE a.component_id = ${format}_component.component_id
)

  AND component_id > #{continuationToken}

ORDER BY component_id

  LIMIT #{limit}

SELECT * FROM ${format}_component
 WHERE (normalized_version IS NULL 
        OR normalized_version = '')
 AND component_id > #{continuationToken}
 ORDER BY component_id LIMIT #{limit};

WITH componentIds AS (
    SELECT component_id FROM ${format}_component
    WHERE repository_id IN

      #{repositoryId}

     AND component_id > #{continuationToken}
     AND kind = #{kind}
     AND (${filter})
    ORDER BY component_id
    LIMIT #{limit}
)
SELECT
    component.*, asset.*
FROM ${format}_component AS component
LEFT JOIN ${format}_asset AS asset ON component.component_id = asset.component_id
WHERE component.component_id IN (select component_id from componentIds)
ORDER BY component.component_id

SELECT component.*, asset.*
FROM (
    SELECT * FROM ${format}_component
    WHERE repository_id IN

      #{repositoryId}

     AND component_id > #{continuationToken}
     AND kind = #{kind}
     AND (${filter})
    ORDER BY component_id
    LIMIT #{limit}
) AS component
LEFT JOIN ${format}_asset AS asset ON component.component_id = asset.component_id
ORDER BY component.component_id

SELECT * FROM ${format}_component
WHERE repository_id IN

  #{repositoryId}

 AND component_id > #{continuationToken}
ORDER BY component_id LIMIT #{limit};

SELECT version FROM ${format}_component
WHERE namespace = #{namespace} AND name = #{name}
AND ;

SELECT DISTINCT namespace, name FROM ${format}_component WHERE repository_id = #{repositoryId}
 AND CONCAT(namespace, '|', name) > #{continuationToken}
ORDER BY namespace ASC, name ASC
 LIMIT #{limit}

mapper.insert:
MERGE INTO ${format}_component (repository_id, namespace, name, kind, version, normalized_version, attributes
, entity_version
)
KEY (repository_id, namespace, name, version)
VALUES (#{component.repositoryId}, #{component.namespace}, #{component.name},
#{component.kind}, #{component.version}, #{component.normalizedVersion}, #{component.attributes}
, 1
);

WITH lock_repo AS (
  SELECT repository_id FROM ${format}_content_repository
  WHERE repository_id = #{component.repositoryId}
  FOR SHARE
)
INSERT INTO ${format}_component (repository_id, namespace, name, kind, version, normalized_version, attributes
, entity_version
)
SELECT #{component.repositoryId}, #{component.namespace}, #{component.name},
       #{component.kind}, #{component.version}, #{component.normalizedVersion}, #{component.attributes}
       , 1
WHERE EXISTS (SELECT 1 FROM lock_repo)
ON CONFLICT(repository_id, namespace, name, version) DO UPDATE SET repository_id = #{component.repositoryId}

mapper.select:
